// Template for the deployed service-worker.js, generated by dist.sh. The
// placeholder tokens below are substituted per build so each deployed
// version gets its own cache name and file lists (old versions' caches are
// cleaned up in the 'activate' handler below).

const CACHE_NAME = 'circuitjs-cache-VERSION_PLACEHOLDER';

// The app shell: the entry page, the JS/CSS it loads up front, the icon font
// and setuplist.txt.  The browser has just downloaded all of these to show
// the page, so precaching them on install costs almost no network.
const shellFiles = [
  'circuitjs.html',
SHELL_FILES_GO_HERE
];

// Every file in this version.  Only fetched on request from the page (see
// the 'message' handler), which happens when it's running as an installed
// app.  Otherwise files are cached by the fetch handler as they're used.
const allFiles = [
  'circuitjs.html',
  'iframe.html',
  'jsinterface.html',
FILE_LIST_GOES_HERE
];

// Cache each file individually rather than with cache.addAll(): addAll is
// all-or-nothing, so a single file the server refuses (e.g. a stray .py the
// web server 403s) would fail the whole install, leaving the previous
// version's worker in control and serving its stale cache indefinitely.
// skipWaiting() activates the new version right away instead of waiting
// for every open tab of the site to close.
self.addEventListener('install', event => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache =>
      Promise.all(shellFiles.map(url =>
        cache.add(url).catch(err => console.warn('Service worker: failed to cache', url, err))
      ))
    )
  );
});

// Download every file in allFiles that isn't cached yet, a few at a time so
// it doesn't compete much with whatever the user is doing.  Safe to repeat:
// after the first complete run it's just a cache lookup per file, and a run
// that was interrupted (worker killed, network lost) picks up where it left
// off next time.
let cacheAllPromise = null;
function cacheAllFiles() {
  if (cacheAllPromise)
    return cacheAllPromise;
  cacheAllPromise = caches.open(CACHE_NAME).then(cache => {
    let next = 0;
    const worker = async () => {
      while (next < allFiles.length) {
        const url = allFiles[next++];
        try {
          if (!(await cache.match(url)))
            await cache.add(url);
        } catch (err) {
          console.warn('Service worker: failed to cache', url, err);
        }
      }
    };
    return Promise.all([worker(), worker(), worker(), worker()]);
  }).finally(() => { cacheAllPromise = null; });
  return cacheAllPromise;
}

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'cacheAll')
    event.waitUntil(cacheAllFiles());
});

self.addEventListener('fetch', (event) => {
    // Normalize the request URL by stripping the ?startCircuit parameter
    let req = event.request;
    const url = new URL(req.url);

    if (url.searchParams.has('startCircuit')) {
        // Remove the 'startCircuit' query parameter
        url.searchParams.delete('startCircuit');
        const request = event.request;
        req = new Request(url, {
                    method: request.method,
                    headers: request.headers,
                    mode: request.mode === 'navigate' ? 'same-origin' : request.mode,
                    credentials: request.credentials,
                    redirect: request.redirect,
                    referrer: request.referrer,
                    integrity: request.integrity,
                    cache: request.caches });
    }

    event.respondWith(
        caches.match(req).then((cachedResponse) => {
            if (cachedResponse) {
                // If the resource is already cached, return it
                return cachedResponse;
            }

            // Otherwise, fetch it from the network and add it to the cache
            return fetch(req).then((networkResponse) => {
                if (
                    event.request.method === 'GET' &&
                    networkResponse.status === 200
                ) {
                    const responseClone = networkResponse.clone();
                    caches.open(CACHE_NAME).then((cache) => {
                        cache.put(req, responseClone);
                    });
                }

                return networkResponse;
            });
        })
    );
});

// Activate event: cleans up old caches
self.addEventListener('activate', (event) => {
    const cacheWhitelist = [CACHE_NAME];  // List of cache versions you want to keep

    event.waitUntil(
        caches.keys().then((cacheNames) => {
            return Promise.all(
                cacheNames.map((cacheName) => {
                    if (!cacheWhitelist.includes(cacheName)) {
                        return caches.delete(cacheName);  // Delete old caches that aren't in whitelist
                    }
                })
            );
        }).then(() => self.clients.claim())
    );
});
